import{_ as s,c as a,d as e,o as t}from"./app-C-xO4nky.js";const o={};function p(l,n){return t(),a("div",null,[...n[0]||(n[0]=[e(`<h1 id="gowind-shop-出海实战-多语言商品内容怎么存、怎么录、怎么按-locale-取" tabindex="-1"><a class="header-anchor" href="#gowind-shop-出海实战-多语言商品内容怎么存、怎么录、怎么按-locale-取"><span>GoWind Shop 出海实战:多语言商品内容怎么存、怎么录、怎么按 locale 取</span></a></h1><h2 id="一个常见误解" tabindex="-1"><a class="header-anchor" href="#一个常见误解"><span>一个常见误解</span></a></h2><p>很多团队对&quot;国际化&quot;的理解停留在前端字符串翻译——<code>zh.json</code>/<code>en.json</code> 切换一下 <code>t(&#39;hello&#39;)</code> 就完事。但对电商而言,真正的难点不在 UI 文案,而在<strong>商品内容的多语言化</strong>。</p><p>一件商品的中文名、英文名、商品描述、类目路径——这些是入库的业务数据,不是 UI 文案。你不能把它们塞进 <code>zh.json</code>,因为:</p><ul><li>不同语言的商品描述要分别审核、分别上下架。</li><li>同一件商品的&quot;主数据&quot;(SKU、价格、库存、类目归属)是语言无关的,只有&quot;展示文案&quot;按语言分叉。</li><li>后台编辑时,运营要在同一界面同时维护所有语言版本,而不是切来切去。</li><li>店铺前台要能按 URL 里的 locale 一次性取到对应语言版本,而不是取全量再前端过滤。</li></ul><p>这篇文章讲一个真实仓库 go-wind-shop(GitHub: <a href="https://github.com/tx7do/go-wind-shop" target="_blank" rel="noopener noreferrer">https://github.com/tx7do/go-wind-shop</a>, Gitee: <a href="https://gitee.com/tx7do/go-wind-shop" target="_blank" rel="noopener noreferrer">https://gitee.com/tx7do/go-wind-shop</a>)怎么从数据层、proto 契约层、后台录入层、前台路由层四个层面,把&quot;多语言商品内容&quot;做成一等公民。最后讲多币种的诚实边界——为什么这套架构的 schema 支持多币种展示,但运行时却收敛到单一结算币种。</p><p>所有代码和配置均可逐行核对。</p><hr><h2 id="一、数据层-base-表-translation-表的分裂模式" tabindex="-1"><a class="header-anchor" href="#一、数据层-base-表-translation-表的分裂模式"><span>一、数据层:base 表 + translation 表的分裂模式</span></a></h2><p>国际化商品内容的核心数据模式是<strong>把语言无关字段和语言相关字段拆成两张表</strong>。这个模式在这个仓库的 5 个目录实体上重复出现:</p><table><thead><tr><th>实体</th><th>语言无关表(主数据)</th><th>语言相关表(翻译)</th></tr></thead><tbody><tr><td>Product</td><td><code>mall_products</code></td><td><code>mall_product_translations</code></td></tr><tr><td>Category</td><td><code>mall_categories</code></td><td><code>mall_category_translations</code></td></tr><tr><td>Brand</td><td><code>mall_brands</code></td><td><code>mall_brand_translations</code></td></tr><tr><td>ProductAttribute</td><td><code>mall_product_attributes</code></td><td><code>mall_product_attribute_translations</code></td></tr><tr><td>ProductAttributeValue</td><td><code>mall_product_attribute_values</code></td><td><code>..._translations</code></td></tr></tbody></table><p>以 Brand 为例。主表 <code>backend/app/core/service/internal/data/ent/schema/brand.go</code> 只有 <code>logo_url</code> 这一个业务字段——它和语言无关:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>Brand<span class="token punctuation">)</span> <span class="token function">Fields</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>ent<span class="token punctuation">.</span>Field <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>ent<span class="token punctuation">.</span>Field<span class="token punctuation">{</span></span>
<span class="line">        field<span class="token punctuation">.</span><span class="token function">String</span><span class="token punctuation">(</span><span class="token string">&quot;logo_url&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Optional</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Nillable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>翻译表 <code>brand_translation.go</code> 承载所有语言相关的文案字段:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>BrandTranslation<span class="token punctuation">)</span> <span class="token function">Fields</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>ent<span class="token punctuation">.</span>Field <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>ent<span class="token punctuation">.</span>Field<span class="token punctuation">{</span></span>
<span class="line">        field<span class="token punctuation">.</span><span class="token function">Uint32</span><span class="token punctuation">(</span><span class="token string">&quot;brand_id&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>      <span class="token comment">// 外键 → 主表</span></span>
<span class="line">        field<span class="token punctuation">.</span><span class="token function">String</span><span class="token punctuation">(</span><span class="token string">&quot;language_code&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token comment">// 语言代码(zh-CN / en-US / ...)</span></span>
<span class="line">        field<span class="token punctuation">.</span><span class="token function">String</span><span class="token punctuation">(</span><span class="token string">&quot;name&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Optional</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        field<span class="token punctuation">.</span><span class="token function">String</span><span class="token punctuation">(</span><span class="token string">&quot;slug&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Optional</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        field<span class="token punctuation">.</span><span class="token function">String</span><span class="token punctuation">(</span><span class="token string">&quot;description&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Optional</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>BrandTranslation<span class="token punctuation">)</span> <span class="token function">Indexes</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>ent<span class="token punctuation">.</span>Index <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>ent<span class="token punctuation">.</span>Index<span class="token punctuation">{</span></span>
<span class="line">        index<span class="token punctuation">.</span><span class="token function">Fields</span><span class="token punctuation">(</span><span class="token string">&quot;brand_id&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;language_code&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Unique</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span>  <span class="token comment">// 复合唯一索引</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>两个设计点:</p><p><strong>1. <code>(brand_id, language_code)</code> 复合唯一索引。</strong> 从数据库层面保证了一件品牌在一门语言下至多一条翻译。既防脏数据,也让&quot;按 locale 取&quot;的查询走索引,而不是全表扫描后过滤。</p><p><strong>2. 主表/翻译表彻底分权。</strong> <code>mall_products</code> 的 Schema 注释里写明&quot;locale 无关&quot;,只存 <code>status</code>、<code>category_id</code>、<code>brand_id</code>、<code>image_url</code> 这种与语言无关的运营字段;所有文案在 <code>mall_product_translations</code>。Product 的翻译表字段更完整:<code>name</code>/<code>slug</code>/<code>short_description</code>/<code>long_description</code>,覆盖商品详情页需要的全部文案。</p><p>这个分权不是洁癖,是工程必需。后面会讲为什么不能用 JSONB 列存多语言——那个方案在这些字段上建不了合适的索引。</p><h3 id="_1-1-producttranslation-的字段结构" tabindex="-1"><a class="header-anchor" href="#_1-1-producttranslation-的字段结构"><span>1.1 ProductTranslation 的字段结构</span></a></h3><p><code>backend/api/protos/catalog/service/v1/product.proto</code> 里 <code>ProductTranslation</code> 消息:</p><div class="language-proto line-numbers-mode" data-highlighter="prismjs" data-ext="proto"><pre><code><span class="line">message ProductTranslation {</span>
<span class="line">  optional uint32 id = 1;</span>
<span class="line">  optional uint32 product_id = 2;       // 外键</span>
<span class="line">  optional string language_code = 3;    // 语言代码</span>
<span class="line">  optional string name = 4;</span>
<span class="line">  optional string slug = 5;</span>
<span class="line">  optional string short_description = 6;</span>
<span class="line">  optional string long_description = 7;</span>
<span class="line">  // ... 审计字段</span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这个消息对应 <code>mall_product_translations</code> 表的一行。注意它和主表 <code>Product</code> 是分离的消息——proto 层面就分开了,不是同一个 message 里的可选字段。</p><hr><h2 id="二、proto-层-把-多语言-写进契约" tabindex="-1"><a class="header-anchor" href="#二、proto-层-把-多语言-写进契约"><span>二、proto 层:把&quot;多语言&quot;写进契约</span></a></h2><p>数据层的分裂模式在 proto 里有对称表达。每个 base 消息内嵌两个相关字段(<code>backend/api/protos/catalog/service/v1/product.proto</code>):</p><div class="language-proto line-numbers-mode" data-highlighter="prismjs" data-ext="proto"><pre><code><span class="line">message Product {</span>
<span class="line">  optional uint32 id = 1;</span>
<span class="line">  // ... 语言无关字段(status, category_id, brand_id, image_url, ...)</span>
<span class="line">  repeated ProductTranslation translations = 20 [...];   // 多语言翻译列表</span>
<span class="line">  repeated string available_languages = 21 [...];        // 该实体已有翻译的语言码集合</span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>translations</code> 是 <code>repeated ProductTranslation</code>,即一个商品的所有语言版本打包在一条消息里。<code>available_languages</code> 是个便利字段,列出该实体当前实际有哪些语言的翻译——后台列表页用它判断&quot;这个商品还缺哪些语言&quot;。</p><p>读取侧,<code>GetProductRequest</code> 暴露 <code>locale</code> 选择器:</p><div class="language-proto line-numbers-mode" data-highlighter="prismjs" data-ext="proto"><pre><code><span class="line">message GetProductRequest {</span>
<span class="line">  optional uint32 id = 1;</span>
<span class="line">  optional string locale = 10 [json_name = &quot;locale&quot;, ...];</span>
<span class="line">  // 注释:语言代码，用于指定返回哪个语言版本的数据</span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这个 <code>locale</code> 字段决定了两种读取模式:</p><ul><li><strong>带 locale 的 Get</strong>:只返回该语言的那一条翻译。店铺前台用这个——它只需要当前 locale 的文案。</li><li><strong>不带 locale 的 List/Get</strong>:返回 <code>translations</code> 全量(所有语言)。后台编辑用这个——运营要同时看到所有语言版本。</li></ul><p>同一个 proto 服务,用 <code>locale</code> 参数区分了两个场景。这比&quot;前台一个接口、后台一个接口&quot;更收敛——数据模型只有一份,接口只有一套,差异只在读取参数。</p><p>每个实体还配了一套<strong>翻译 CRUD RPC</strong>:<code>TranslationExists</code>/<code>GetTranslation</code>/<code>CreateTranslation</code>/<code>UpdateTranslation</code>/<code>DeleteTranslation</code>。这些允许对单条翻译独立操作——比如运营只改了英文版本,可以只 Update 那一条,不用重传整个 <code>translations</code> 数组。</p><h3 id="_2-1-店铺前台-proto-的复用" tabindex="-1"><a class="header-anchor" href="#_2-1-店铺前台-proto-的复用"><span>2.1 店铺前台 proto 的复用</span></a></h3><p>店铺前台的 proto(<code>backend/api/protos/app/service/v1/i_product.proto</code>)直接复用 core 的 <code>ProductService</code>:</p><div class="language-proto line-numbers-mode" data-highlighter="prismjs" data-ext="proto"><pre><code><span class="line">rpc Get (catalog.service.v1.GetProductRequest) returns (catalog.service.v1.Product) {</span>
<span class="line">  option (google.api.http) = { get: &quot;/app/v1/mall/products/{id}&quot; };</span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>注意 <code>GetProductRequest</code> 是 <code>catalog.service.v1</code> 的——app BFF proto 只是给 <code>/app/v1/mall/products/{id}</code> 这条路由做了 HTTP 绑定,请求/响应类型完全复用 core 的。所以 <code>locale</code> 选择器对前台同样可用:前台取商品时带上 URL 里的 locale,后端就只返回那一种语言的文案。</p><p>这是契约驱动的收益之一:<strong>前台/后台共享同一套数据契约,差异只在传输绑定和 locale 参数,不需要为前台单独定义一套&quot;精简版&quot;消息。</strong></p><hr><h2 id="三、语言字典-哪些语言-存在-是受控的" tabindex="-1"><a class="header-anchor" href="#三、语言字典-哪些语言-存在-是受控的"><span>三、语言字典:哪些语言&quot;存在&quot;,是受控的</span></a></h2><p>&quot;支持哪些语言&quot;不是写死在代码里,而是受一张字典表控制。<code>backend/api/protos/dict/service/v1/language.proto</code> 定义了 <code>LanguageService</code> 与 <code>Language</code> 消息:</p><div class="language-proto line-numbers-mode" data-highlighter="prismjs" data-ext="proto"><pre><code><span class="line">message Language {</span>
<span class="line">  optional uint32 id = 1;</span>
<span class="line">  optional string language_code = 2;    // e.g. zh-CN</span>
<span class="line">  optional string language_name = 3;    // 系统名(英文显示名)</span>
<span class="line">  optional string native_name = 4;      // 母语名(&quot;中文&quot;/&quot;English&quot;)</span>
<span class="line">  optional bool is_default = 5;         // 是否默认语言</span>
<span class="line">  optional bool is_enabled = 6;         // 是否启用</span>
<span class="line">  optional int32 sort_order = 7;        // 掁序</span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>后台有配套的 CRUD 页面 <code>frontend/admin/src/pages/app/system/language/index.vue</code>,运营可以在这里增删语言、开关 <code>is_enabled</code>、设置默认语言。这个开关<strong>直接决定后台编辑界面会渲染几个语言 tab</strong>——禁用的语言不会出现在录入界面里。</p><p>这个设计的关键价值在第三节讲——把&quot;语言清单&quot;做成受控字典,而不是前端硬编码。</p><hr><h2 id="四、后台录入-translationtabs-组件-一处编辑所有语言" tabindex="-1"><a class="header-anchor" href="#四、后台录入-translationtabs-组件-一处编辑所有语言"><span>四、后台录入:TranslationTabs 组件,一处编辑所有语言</span></a></h2><p>这是整个国际化方案里工程量最大、也最值得讲的一块。</p><p>一个朴素的实现是:为每个实体、每种语言分别做一个编辑页。这会导致页面爆炸——5 个实体 × 2 种语言 = 10 个页面,而且新增一个语种要再翻一倍。这个仓库没这么做,而是抽象出了一个<strong>可复用的 <code>TranslationTabs</code> 组件</strong>。</p><h3 id="_4-1-组件契约-声明式字段配置" tabindex="-1"><a class="header-anchor" href="#_4-1-组件契约-声明式字段配置"><span>4.1 组件契约:声明式字段配置</span></a></h3><p><code>frontend/admin/src/components/Pro/TranslationTabs/types.ts</code>:</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code><span class="line"><span class="token keyword">export</span> <span class="token keyword">interface</span> <span class="token class-name">TranslationFieldConfig</span> <span class="token punctuation">{</span></span>
<span class="line">  prop<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span>        <span class="token comment">// 绑定到 translations[i] 的哪个字段</span></span>
<span class="line">  label<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span>       <span class="token comment">// 字段标题</span></span>
<span class="line">  type<span class="token operator">:</span> <span class="token string">&quot;input&quot;</span> <span class="token operator">|</span> <span class="token string">&quot;textarea&quot;</span> <span class="token operator">|</span> <span class="token string">&quot;input-number&quot;</span><span class="token punctuation">;</span>  <span class="token comment">// 渲染哪种表单控件</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>父组件(各实体的 drawer)只需声明&quot;我要编辑哪几个翻译字段&quot;,其余渲染逻辑交给 <code>TranslationTabs</code>。</p><h3 id="_4-2-组件行为-字典驱动-每语言一条保证" tabindex="-1"><a class="header-anchor" href="#_4-2-组件行为-字典驱动-每语言一条保证"><span>4.2 组件行为:字典驱动 + 每语言一条保证</span></a></h3><p><code>frontend/admin/src/components/Pro/TranslationTabs/index.vue</code> 的核心逻辑:</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code><span class="line"><span class="token function">onMounted</span><span class="token punctuation">(</span><span class="token keyword">async</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">// 拉取语言字典,只保留 is_enabled 的语种</span></span>
<span class="line">  <span class="token keyword">const</span> <span class="token punctuation">{</span> data <span class="token punctuation">}</span> <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token function">fetchListLanguages</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token comment">/* paging */</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token keyword">const</span> enabled <span class="token operator">=</span> <span class="token punctuation">(</span>data<span class="token operator">?.</span>list <span class="token operator">??</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">filter</span><span class="token punctuation">(</span>l <span class="token operator">=&gt;</span> l<span class="token punctuation">.</span>isEnabled <span class="token operator">===</span> <span class="token boolean">true</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token comment">// 为每个启用语言确保 translations 数组里有一条记录</span></span>
<span class="line">  enabled<span class="token punctuation">.</span><span class="token function">forEach</span><span class="token punctuation">(</span>lang <span class="token operator">=&gt;</span> <span class="token function">getOrCreateEntry</span><span class="token punctuation">(</span>lang<span class="token punctuation">.</span>languageCode<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">getOrCreateEntry</span><span class="token punctuation">(</span>languageCode<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">// 如果 formData.translations 里没有该 languageCode 的条目,创建一个空条目</span></span>
<span class="line">  <span class="token keyword">const</span> existing <span class="token operator">=</span> formData<span class="token punctuation">.</span>translations<span class="token punctuation">.</span><span class="token function">find</span><span class="token punctuation">(</span>t <span class="token operator">=&gt;</span> t<span class="token punctuation">.</span>languageCode <span class="token operator">===</span> languageCode<span class="token punctuation">)</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>existing<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    formData<span class="token punctuation">.</span>translations<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span><span class="token punctuation">{</span> languageCode<span class="token punctuation">,</span> <span class="token comment">/* 空字段 */</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>然后模板渲染:</p><div class="language-vue line-numbers-mode" data-highlighter="prismjs" data-ext="vue"><pre><code><span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>el-tabs</span><span class="token punctuation">&gt;</span></span></span>
<span class="line">  <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>el-tab-pane</span></span>
<span class="line">    <span class="token attr-name">v-for</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>lang in enabledLanguages<span class="token punctuation">&quot;</span></span></span>
<span class="line">    <span class="token attr-name">:key</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>lang.languageCode<span class="token punctuation">&quot;</span></span></span>
<span class="line">    <span class="token attr-name">:label</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>lang.nativeName || lang.languageName || lang.languageCode<span class="token punctuation">&quot;</span></span></span>
<span class="line">  <span class="token punctuation">&gt;</span></span></span>
<span class="line">    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>el-form</span><span class="token punctuation">&gt;</span></span></span>
<span class="line">      <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>el-form-item</span></span>
<span class="line">        <span class="token attr-name">v-for</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>field in translationFields<span class="token punctuation">&quot;</span></span></span>
<span class="line">        <span class="token attr-name">:label</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>field.label<span class="token punctuation">&quot;</span></span></span>
<span class="line">      <span class="token punctuation">&gt;</span></span></span>
<span class="line">        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>component</span></span>
<span class="line">          <span class="token attr-name">:is</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>resolveComponent(field.type)<span class="token punctuation">&quot;</span></span></span>
<span class="line">          <span class="token attr-name">v-model</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>getEntry(lang.languageCode)[field.prop]<span class="token punctuation">&quot;</span></span></span>
<span class="line">        <span class="token punctuation">/&gt;</span></span></span>
<span class="line">      <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>el-form-item</span><span class="token punctuation">&gt;</span></span></span>
<span class="line">    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>el-form</span><span class="token punctuation">&gt;</span></span></span>
<span class="line">  <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>el-tab-pane</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>el-tabs</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>几个关键点逐条说明:</p><p><strong>字典驱动。</strong> 组件挂载时调 <code>fetchListLanguages</code>(对应 <code>dict.LanguageService.List</code>),拉取语言字典,<code>filter(l =&gt; l.isEnabled === true)</code> 只保留启用的语种。Tab 的数量和顺序完全由字典决定,组件本身不硬编码任何语言。运营在&quot;语言管理&quot;页面新增一个语种并启用,所有用了 <code>TranslationTabs</code> 的实体编辑页<strong>无需重新部署</strong>就会出现新 tab。</p><p><strong>每语言一条保证。</strong> <code>getOrCreateEntry</code> + <code>watchEffect</code> 确保 <code>formData.translations</code> 数组里<strong>永远为每个启用语言保留一条记录</strong>——哪怕运营不填某语言,那条空记录也在。提交时不会丢语言槽位,后端也不会因为缺某语言而把已有翻译覆盖成空。</p><p><strong>v-model 直绑后端载荷。</strong> <code>formData.translations</code> 直接绑定到后端 <code>XxxTranslation[]</code> 载荷——没有中间映射层,组件渲染的就是后端要存的数据结构。这避免了&quot;前端表单字段和后端 DTO 字段名不一致&quot;的经典 bug。</p><p><strong>字段声明式。</strong> <code>translationFields</code> 决定每个 tab 里渲染几个输入框、什么类型。新增一个可翻译字段,只需要在 Schema/proto 加字段、在 drawer 的 <code>translationFields</code> 加一行——UI 自动就位,无需写新组件。</p><h3 id="_4-3-各实体怎么用" tabindex="-1"><a class="header-anchor" href="#_4-3-各实体怎么用"><span>4.3 各实体怎么用</span></a></h3><p>实体 drawer 声明字段并嵌入组件。<code>frontend/admin/src/pages/app/mall/product/product-drawer.vue</code>:</p><div class="language-vue line-numbers-mode" data-highlighter="prismjs" data-ext="vue"><pre><code><span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>TranslationTabs</span></span>
<span class="line">  <span class="token attr-name">v-model</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>formData.translations<span class="token punctuation">&quot;</span></span></span>
<span class="line">  <span class="token attr-name">:translation-fields</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>[</span>
<span class="line">    { prop: &#39;name&#39;,             label: t(&#39;mall.product.name&#39;),             type: &#39;input&#39; },</span>
<span class="line">    { prop: &#39;slug&#39;,             label: t(&#39;mall.product.slug&#39;),             type: &#39;input&#39; },</span>
<span class="line">    { prop: &#39;shortDescription&#39;, label: t(&#39;mall.product.shortDescription&#39;), type: &#39;textarea&#39; },</span>
<span class="line">    { prop: &#39;longDescription&#39;,  label: t(&#39;mall.product.longDescription&#39;),  type: &#39;textarea&#39; },</span>
<span class="line">  ]<span class="token punctuation">&quot;</span></span></span>
<span class="line"><span class="token punctuation">/&gt;</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Brand、Category、ProductAttribute、ProductAttributeValue 的 drawer 同理,各自声明自己的字段集合:</p><table><thead><tr><th>Drawer</th><th>翻译字段</th></tr></thead><tbody><tr><td><code>product-drawer.vue</code></td><td>name, slug, shortDescription, longDescription</td></tr><tr><td><code>category-drawer.vue</code></td><td>name, slug, description, fullPath</td></tr><tr><td><code>brand-drawer.vue</code></td><td>name, slug, description</td></tr><tr><td><code>product-attribute-drawer.vue</code></td><td>name</td></tr><tr><td><code>product-attribute-value-drawer.vue</code></td><td>displayName</td></tr></tbody></table><p>注意 <code>category-drawer.vue</code> 里有 <code>fullPath</code>——这个字段存的是带 locale 前缀的类目路径,下一节解释为什么。</p><h3 id="_4-4-列表页怎么展示" tabindex="-1"><a class="header-anchor" href="#_4-4-列表页怎么展示"><span>4.4 列表页怎么展示</span></a></h3><p>列表页(<code>brand/index.vue</code> 等)展示的是&quot;当前后台 UI 语言&quot;那一条翻译:</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code><span class="line"><span class="token keyword">const</span> <span class="token function-variable function">cellText</span> <span class="token operator">=</span> <span class="token punctuation">(</span>row<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> t <span class="token operator">=</span> row<span class="token punctuation">.</span>translations<span class="token punctuation">.</span><span class="token function">find</span><span class="token punctuation">(</span>t <span class="token operator">=&gt;</span> t<span class="token punctuation">.</span>languageCode <span class="token operator">===</span> locale<span class="token punctuation">.</span>value<span class="token punctuation">)</span></span>
<span class="line">  <span class="token keyword">return</span> t<span class="token operator">?.</span>name <span class="token operator">??</span> <span class="token string">&#39;-&#39;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>即:表格里看到的是中文(因为运营切到了中文 UI),但点开 drawer 看到的是所有语言 tab。运营切 UI 语言,列表的展示语言也跟着切——因为展示的数据本来就是按语言分库的,切换 locale 只是查不同语言的那一行。</p><p>这个设计的巧妙之处:<strong>列表和编辑用同一套 translations 数据,差异只在 locale 参数。列表是&quot;单语言视图&quot;(当前 UI 语言),drawer 是&quot;全语言视图&quot;(所有 tab)。无需为&quot;多语言列表&quot;单独设计数据结构。</strong></p><hr><h2 id="五、店铺前台-url-locale-作为路由一等公民" tabindex="-1"><a class="header-anchor" href="#五、店铺前台-url-locale-作为路由一等公民"><span>五、店铺前台:URL locale 作为路由一等公民</span></a></h2><p>前台(Nuxt)用 <a href="https://i18n.nuxtjs.org/" target="_blank" rel="noopener noreferrer"><code>@nuxtjs/i18n</code></a>。配置在 <code>frontend/app/nuxt.config.ts</code>:</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code><span class="line">i18n<span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">  langDir<span class="token operator">:</span> <span class="token string">&#39;../locales&#39;</span><span class="token punctuation">,</span></span>
<span class="line">  locales<span class="token operator">:</span> <span class="token punctuation">[</span></span>
<span class="line">    <span class="token punctuation">{</span> code<span class="token operator">:</span> <span class="token string">&#39;zh-CN&#39;</span><span class="token punctuation">,</span> iso<span class="token operator">:</span> <span class="token string">&#39;zh-CN&#39;</span><span class="token punctuation">,</span> name<span class="token operator">:</span> <span class="token string">&#39;中文&#39;</span><span class="token punctuation">,</span>    file<span class="token operator">:</span> <span class="token string">&#39;zh-CN/index.ts&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">{</span> code<span class="token operator">:</span> <span class="token string">&#39;en-US&#39;</span><span class="token punctuation">,</span> iso<span class="token operator">:</span> <span class="token string">&#39;en-US&#39;</span><span class="token punctuation">,</span> name<span class="token operator">:</span> <span class="token string">&#39;English&#39;</span><span class="token punctuation">,</span> file<span class="token operator">:</span> <span class="token string">&#39;en-US/index.ts&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">  defaultLocale<span class="token operator">:</span> <span class="token string">&#39;zh-CN&#39;</span><span class="token punctuation">,</span></span>
<span class="line">  strategy<span class="token operator">:</span> <span class="token string">&#39;prefix&#39;</span><span class="token punctuation">,</span>                  <span class="token comment">// locale 编码进 URL 路径前缀</span></span>
<span class="line">  detectBrowserLanguage<span class="token operator">:</span> <span class="token boolean">false</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>几个关键决策:</p><p><strong><code>strategy: &#39;prefix&#39;</code>。</strong> locale 编码进 URL 路径,即 <code>/zh-CN/category/tech</code>、<code>/en-US/category/tech</code>。同一个类目在两种语言下有两个独立 URL。这契合了 <code>CategoryTranslation.full_path</code> 字段——它存的就是带 locale 前缀的路径,proto 注释里的示例正是 <code>/zh-CN/category/tech</code>。</p><p><strong><code>detectBrowserLanguage: false</code>。</strong> 不根据浏览器 <code>Accept-Language</code> 自动重定向。出海场景下,自动跳转常被搜索爬虫和地区合规要求打乱——比如某地区要求默认展示某语言,但浏览器设了另一种,自动跳转会违背合规要求。显式 URL 更可控。</p><p><strong>静态根跳转。</strong> nuxt.config 里有一段 SSG 逻辑把 <code>/</code> 重定向到 <code>/zh-CN/</code>,保证默认语言也有稳定入口,避免访问根路径时 404。</p><h3 id="_5-1-翻译文案文件结构" tabindex="-1"><a class="header-anchor" href="#_5-1-翻译文案文件结构"><span>5.1 翻译文案文件结构</span></a></h3><p><code>frontend/app/locales/{zh-CN,en-US}/</code> 下按业务域分文件:</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">frontend/app/locales/</span>
<span class="line">├── zh-CN/</span>
<span class="line">│   ├── addresses.json</span>
<span class="line">│   ├── cart.json</span>
<span class="line">│   ├── checkout.json</span>
<span class="line">│   ├── mall.json          ← 含 currencyCny 等</span>
<span class="line">│   ├── navbar.json</span>
<span class="line">│   ├── orders.json</span>
<span class="line">│   ├── shipment.json</span>
<span class="line">│   ├── ui.json</span>
<span class="line">│   └── ... (20+ 命名空间)</span>
<span class="line">└── en-US/</span>
<span class="line">    └── ... (对称结构)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>每个文件是一个命名空间,代码里 <code>t(&#39;mall.product.price&#39;)</code> 这种点路径定位到 <code>mall.json</code> 里的 <code>product.price</code>。命名空间按业务域分,而不是按页面分——这样新增页面时复用已有命名空间,不会产生&quot;每个页面一个翻译文件&quot;的爆炸。</p><p>布局组件(<code>layouts/default.vue</code>)在 <code>$i18n.locale</code> 变化时给整棵组件树 re-key,触发完全重渲染——语言切换是即时的,不需要刷新页面。</p><h3 id="_5-2-前台取商品时的-locale-传递" tabindex="-1"><a class="header-anchor" href="#_5-2-前台取商品时的-locale-传递"><span>5.2 前台取商品时的 locale 传递</span></a></h3><p>前台调用商品接口时,<code>locale</code> 参数从 URL 路径取。<code>frontend/app/app/utils/locale.ts</code>:</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code><span class="line"><span class="token keyword">export</span> <span class="token keyword">function</span> <span class="token function">getCurrentLocale</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">:</span> <span class="token builtin">string</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">// 从 nuxt i18n 运行时取当前 locale</span></span>
<span class="line">  <span class="token comment">// 默认 zh-CN</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这个值在 API composable 里被塞进请求的 <code>locale</code> 字段,后端据此只返回该语言的翻译。整条链路:URL 路径 <code>/zh-CN/...</code> → nuxt i18n 解析出 locale → API 请求带 locale → core 只返回该语言翻译 → 前端渲染。locale 从 URL 到 DB 查询,全程显式传递,不靠隐式状态。</p><h3 id="_5-3-一个已知边界" tabindex="-1"><a class="header-anchor" href="#_5-3-一个已知边界"><span>5.3 一个已知边界</span></a></h3><p><code>frontend/app/app/core/preferences/types/layout.ts</code> 里:</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code><span class="line"><span class="token keyword">export</span> <span class="token keyword">type</span> <span class="token class-name">SupportedLanguagesType</span> <span class="token operator">=</span> <span class="token string">&quot;zh-CN&quot;</span> <span class="token operator">|</span> <span class="token string">&quot;en-US&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>这个类型是硬编码的——即新增一个语种时,除了在语言字典里启用、补 <code>locales/</code> 文件,这里也要扩类型。这是个待优化点:理想情况下该类型应该由语言字典动态生成。当前硬编码是工程权衡(类型系统无法直接吃运行时字典),新增语种需要改三处(字典、locale 文件、类型),不算理想但可控。</p><hr><h2 id="六、横向对比-四种多语言内容存储方案" tabindex="-1"><a class="header-anchor" href="#六、横向对比-四种多语言内容存储方案"><span>六、横向对比:四种多语言内容存储方案</span></a></h2><p>把这套 base/translation 分裂模式和另外三种方案对比。</p><h3 id="方案-a-jsonb-列存多语言-主流方案之一" tabindex="-1"><a class="header-anchor" href="#方案-a-jsonb-列存多语言-主流方案之一"><span>方案 A:JSONB 列存多语言(主流方案之一)</span></a></h3><p>主表加一个 <code>translations JSONB</code> 列,存 <code>{&quot;zh-CN&quot;: {&quot;name&quot;: &quot;...&quot;}, &quot;en-US&quot;: {&quot;name&quot;: &quot;...&quot;}}</code>。</p><ul><li><strong>优点</strong>:一张表,结构简单,新增语言不动 schema。</li><li><strong>缺点</strong>: <ul><li><strong>索引建不起来</strong>:按 locale 取某语言,是 <code>translations-&gt;&gt;&#39;zh-CN&#39;</code> 这种 JSON 路径访问,PostgreSQL 的表达式索引能建但维护成本高,且优化器常常不走。</li><li><strong>字段级约束缺失</strong>:JSONB 内部的 <code>name</code> 字段长度、类型、可空性,数据库没法约束,全靠应用层。</li><li><strong>事务一致性复杂</strong>:更新某语言的 name 要读出整个 JSON、改一处、写回,并发写冲突靠行锁,粒度粗。</li><li><strong>跨语言查询难</strong>:统计&quot;哪些商品缺英文翻译&quot;要展开 JSON,效率差。</li></ul></li></ul><p>这个仓库没选它,核心原因就是索引和字段约束。商品详情页每次访问都要按 locale 取一条翻译,这是高频读,必须走索引。JSONB 的路径访问走不了合适的索引。</p><h3 id="方案-b-每语言一张表" tabindex="-1"><a class="header-anchor" href="#方案-b-每语言一张表"><span>方案 B:每语言一张表</span></a></h3><p><code>brands_zh</code>、<code>brands_en</code> 各一张表,列相同。</p><ul><li><strong>优点</strong>:每张表物理隔离,查询无 locale 过滤。</li><li><strong>缺点</strong>:语言数 N → 表数 N,运营新增语言要 DDL 建表;跨语言聚合(如&quot;全量商品列表&quot;)要 UNION N 张表;ORM 映射爆炸。</li></ul><p>这是最差的方案,几乎没有优点。适合语言数固定且极少(如 2)的小项目,不适合出海场景(语言数会增长)。</p><h3 id="方案-c-本方案-base-translation-分裂-复合唯一索引" tabindex="-1"><a class="header-anchor" href="#方案-c-本方案-base-translation-分裂-复合唯一索引"><span>方案 C(本方案):base + translation 分裂 + 复合唯一索引</span></a></h3><p>主表存语言无关字段,翻译表存 <code>(entity_id, language_code, 文案字段)</code>,复合唯一索引 <code>(entity_id, language_code)</code>。</p><ul><li><strong>优点</strong>: <ul><li><strong>索引可用</strong>:按 locale 取翻译是 <code>WHERE entity_id = ? AND language_code = ?</code>,走复合唯一索引,O(log n)。</li><li><strong>字段级约束齐全</strong>:每个文案字段都是正常的列,长度、类型、可空性数据库层约束。</li><li><strong>事务粒度细</strong>:更新某语言只锁那一行,不影响其他语言。</li><li><strong>新增语言不动 schema</strong>:加一种语言只是翻译表多几行,主表和翻译表结构都不变。</li></ul></li><li><strong>缺点</strong>: <ul><li>JOIN:取商品+翻译要 JOIN 两张表。但这是 ORM 该处理的,Ent 的关系映射自动 JOIN,业务代码无感。</li><li>表数翻倍:每个实体 2 张表。但这是结构清晰的代价,可接受。</li></ul></li></ul><p>这个方案是主流电商(包括 Shopify、Amazon 的早期架构)用的模式。它在索引可用性、字段约束、事务粒度、可扩展性四个维度上都优于 JSONB 和&quot;每语言一表&quot;。</p><h3 id="方案-d-url-locale-的三种策略对比" tabindex="-1"><a class="header-anchor" href="#方案-d-url-locale-的三种策略对比"><span>方案 D:URL locale 的三种策略对比</span></a></h3><p><code>@nuxtjs/i18n</code> 支持三种 locale 编码策略:<code>prefix</code>(<code>/zh-CN/...</code>)、<code>subdomain</code>(<code>zh.example.com/...</code>)、<code>cookie</code>(URL 不变,cookie 记 locale)。三者的取舍:</p><table><thead><tr><th>策略</th><th>SEO</th><th>缓存</th><th>合规</th><th>实现复杂度</th></tr></thead><tbody><tr><td>prefix</td><td>✅ 每语言独立 URL,可被爬虫索引</td><td>✅ CDN 可按 URL 缓存</td><td>✅ 显式,易审计</td><td>低</td></tr><tr><td>subdomain</td><td>✅ 独立域名</td><td>⚠️ 需泛域名证书</td><td>⚠️ 部分地区对子域名有特殊监管</td><td>中(需 DNS/证书)</td></tr><tr><td>cookie</td><td>❌ 同 URL 不同内容,爬虫困惑</td><td>❌ CDN 缓存失效</td><td>❌ 隐式,难审计</td><td>低</td></tr></tbody></table><p>这个仓库选 <code>prefix</code>,理由是 SEO 和缓存。电商前台的流量很大比例来自搜索引擎,每语言独立 URL 是被索引的前提;CDN 按 URL 缓存也是按 URL 命中,cookie 策略会让 CDN 缓存错乱。subdomain 在 SEO 上也 OK,但需要泛域名证书和 DNS 配置,工程复杂度高。prefix 是 SEO/缓存/复杂度三者最优的折中。</p><hr><h2 id="七、多币种-展示层支持多币种-结算层收敛单一币种" tabindex="-1"><a class="header-anchor" href="#七、多币种-展示层支持多币种-结算层收敛单一币种"><span>七、多币种:展示层支持多币种,结算层收敛单一币种</span></a></h2><p>出海电商的币种设计有个矛盾:展示侧希望按用户地区显示当地币种价格(便于心智),但结算侧必须收敛到单一币种(否则对账和财务不可控)。这套架构的设计叫&quot;<strong>多币种展示 + 单一结算币种</strong>&quot;——但实际运行时,展示层也只跑了单一币种。这节讲清楚为什么。</p><h3 id="_7-1-展示层-sku-多币种价格表的-schema" tabindex="-1"><a class="header-anchor" href="#_7-1-展示层-sku-多币种价格表的-schema"><span>7.1 展示层:SKU 多币种价格表的 schema</span></a></h3><p><code>backend/api/protos/catalog/service/v1/sku.proto</code> 定义了 <code>SkuPrice</code>:</p><div class="language-proto line-numbers-mode" data-highlighter="prismjs" data-ext="proto"><pre><code><span class="line">message SkuPrice {</span>
<span class="line">  optional uint32 id = 1;</span>
<span class="line">  optional uint32 sku_id = 2 [...];          // 外键 → SKU</span>
<span class="line">  optional string currency = 3 [...];        // 币种(ISO 4217，如 CNY/USD/EUR)</span>
<span class="line">  optional string amount  = 4 [...];         // 该币种下的价格金额</span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>amount</code> 用字符串而非浮点——这是金融场景的基本常识,避免二进制浮点精度丢失(0.1 + 0.2 ≠ 0.3)。Ent 对应表 <code>mall_sku_prices</code>,带复合唯一索引:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token comment">// backend/app/core/service/internal/data/ent/schema/sku_price.go</span></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>SkuPrice<span class="token punctuation">)</span> <span class="token function">Indexes</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>ent<span class="token punctuation">.</span>Index <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>ent<span class="token punctuation">.</span>Index<span class="token punctuation">{</span></span>
<span class="line">        index<span class="token punctuation">.</span><span class="token function">Fields</span><span class="token punctuation">(</span><span class="token string">&quot;sku_id&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;currency&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Unique</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span>  <span class="token comment">// 一个 SKU 在一种币种下只有一条价格</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>Schema 层是支持多币种的</strong>:一个 SKU 可以有多条价格,每条对应一种 currency。</p><h3 id="_7-2-结算层-currency-mixin-默认且当前仅-cny" tabindex="-1"><a class="header-anchor" href="#_7-2-结算层-currency-mixin-默认且当前仅-cny"><span>7.2 结算层:Currency mixin 默认且当前仅 CNY</span></a></h3><p>但实际能写入的币种受 <code>backend/pkg/entgo/mixin/currency.go</code> 约束:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line">field<span class="token punctuation">.</span><span class="token function">String</span><span class="token punctuation">(</span><span class="token string">&quot;currency&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">    <span class="token function">Optional</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Nillable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">    <span class="token function">Default</span><span class="token punctuation">(</span><span class="token string">&quot;CNY&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">    <span class="token function">Comment</span><span class="token punctuation">(</span><span class="token string">&quot;币种（ISO 4217，当前仅支持CNY）&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>Default(&quot;CNY&quot;)</code> + 注释&quot;当前仅支持CNY&quot;——schema 预留了多币种字段,但运行时收敛到 CNY。</p><p>订单侧的结算币种也是收敛的。<code>backend/api/protos/order/service/v1/order.proto</code> 的 <code>Order</code>:</p><div class="language-proto line-numbers-mode" data-highlighter="prismjs" data-ext="proto"><pre><code><span class="line">message Order {</span>
<span class="line">  optional string currency = 8 [...];      // 结算币种(ISO 4217)</span>
<span class="line">  optional int64 total_amount = 9 [...];   // 订单总金额(最小货币单位，分)</span>
<span class="line">  // ...</span>
<span class="line">}</span>
<span class="line">message OrderItem {</span>
<span class="line">  optional int64 unit_price = 7 [...];     // 单价(最小货币单位，分)</span>
<span class="line">  optional int64 subtotal = 8 [...];       // 小计(最小货币单位，分)</span>
<span class="line">  optional string sku_snapshot = 9 [...];  // 下单时 SKU 快照(JSON)</span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>几个关键设计:</p><ul><li><strong>金额用 int64 存最小货币单位(分)</strong>,不是浮点。这与 <code>SkuPrice.amount</code> 的字符串设计目的一致——避免浮点精度问题。</li><li><strong><code>sku_snapshot</code> 冻结下单时的 SKU 信息</strong>。后续 SKU 改价、改名、改属性,不影响历史订单。这是电商订单系统的标准设计——订单是&quot;那一刻交易的快照&quot;,不是&quot;当前商品的引用&quot;。</li><li><strong>结算币种字段存在,但运行时只填 CNY</strong>。</li></ul><h3 id="_7-3-前台消费-目前实际只取-cny-那一行" tabindex="-1"><a class="header-anchor" href="#_7-3-前台消费-目前实际只取-cny-那一行"><span>7.3 前台消费:目前实际只取 CNY 那一行</span></a></h3><p>店铺前台读取 <code>prices[]</code> 数组时的逻辑(<code>frontend/app/app/pages/cart.vue</code>):</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code><span class="line"><span class="token keyword">const</span> cny <span class="token operator">=</span> prices<span class="token punctuation">.</span><span class="token function">find</span><span class="token punctuation">(</span>p <span class="token operator">=&gt;</span> p<span class="token punctuation">.</span>currency <span class="token operator">===</span> <span class="token string">&#39;CNY&#39;</span><span class="token punctuation">)</span> <span class="token operator">??</span> prices<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span></span>
<span class="line"><span class="token keyword">if</span> <span class="token punctuation">(</span>cny<span class="token operator">?.</span>amount<span class="token punctuation">)</span> <span class="token punctuation">{</span> skuPricesMap<span class="token punctuation">[</span>skuId<span class="token punctuation">]</span> <span class="token operator">=</span> cny<span class="token punctuation">.</span>amount <span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>币种符号来自 i18n 文案(<code>frontend/app/locales/zh-CN/mall.json</code> 和 <code>en-US/mall.json</code> 都定义了):</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code><span class="line"><span class="token punctuation">{</span> <span class="token property">&quot;currencyCny&quot;</span><span class="token operator">:</span> <span class="token string">&quot;￥&quot;</span> <span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>UI 拼接(<code>cart.vue</code>):</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code><span class="line"><span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span><span class="token function">t</span><span class="token punctuation">(</span><span class="token string">&#39;mall.product.currencyCny&#39;</span><span class="token punctuation">)</span><span class="token interpolation-punctuation punctuation">}</span></span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>selectedAmount<span class="token punctuation">.</span>value<span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">\`</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>下单时,<code>checkout.vue</code> 硬编码结算币种:</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code><span class="line"><span class="token comment">// checkout.vue 创建订单</span></span>
<span class="line"><span class="token keyword">const</span> order <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">// ...</span></span>
<span class="line">  currency<span class="token operator">:</span> <span class="token string">&#39;CNY&#39;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token comment">// ...</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-4-诚实交代当前边界" tabindex="-1"><a class="header-anchor" href="#_7-4-诚实交代当前边界"><span>7.4 诚实交代当前边界</span></a></h3><p>所以&quot;多币种展示 + 单一结算币种&quot;在这套架构里的实际状态:</p><ul><li><strong>Schema/契约层</strong>:已为多币种铺好。<code>SkuPrice</code> 表支持多币种行,复合唯一索引 <code>(sku_id, currency)</code>,字符串金额。</li><li><strong>结算层</strong>:已收敛到单一币种(CNY)。订单/支付都以 CNY 结算,并冻结 <code>sku_snapshot</code>。</li><li><strong>展示层</strong>:目前前台只取 CNY 行。也就是说,<strong>展示层当前是单币种运行</strong>,尽管 schema 允许多币种。</li></ul><p>这不是&quot;没做完&quot;,而是有意的安全保守。原因:</p><p><strong>贸然让前台展示非结算币种的价格,会出现&quot;看到的价和实际扣的不一致&quot;。</strong> 比如 SKU 标价 100 USD,但结算用 CNY,实际扣款是按某汇率折算的 CNY 金额。如果展示的 USD 价格和折算后的 CNY 金额不一致(汇率波动、折算规则差异),用户会投诉,财务对账会乱。</p><p>要真正启用多币种展示,需要三个前置条件:</p><ol><li><strong>接入受控汇率源</strong>:一个可信的、带时间戳的汇率 API,所有展示币种→结算币种的换算都用它。</li><li><strong>明确的展示/结算分离提示</strong>:UI 要明确告诉用户&quot;展示价格仅供参考,结算以 CNY 为准&quot;。</li><li><strong>扩 Currency mixin 的币种白名单</strong>:当前 <code>Default(&quot;CNY&quot;)</code> + &quot;仅支持CNY&quot;的注释要改成支持多币种,且要明确哪些币种允许展示。</li></ol><p>这套架构已经为这条路预留了空间(schema 和 proto 都支持),但运行时守了底线——在没有受控汇率源和合规提示前,不展示非结算币种。这是&quot;宁可功能少,不可数据错&quot;的工程保守。</p><h3 id="_7-5-对比-三种币种策略" tabindex="-1"><a class="header-anchor" href="#_7-5-对比-三种币种策略"><span>7.5 对比:三种币种策略</span></a></h3><table><thead><tr><th>策略</th><th>展示</th><th>结算</th><th>风险</th></tr></thead><tbody><tr><td>全币种结算</td><td>多币种</td><td>多币种</td><td>对账复杂,汇率风险,合规难</td></tr><tr><td>单币种(无多币种能力)</td><td>单币种</td><td>单币种</td><td>无扩展空间,新增币种要改 schema</td></tr><tr><td>本方案:多币种展示+单一结算</td><td>schema 支持多币种,运行时单币种</td><td>单一币种</td><td>展示/结算一致,有扩展空间</td></tr></tbody></table><p>本方案的取舍:<strong>schema 留口子,运行守底线</strong>。在没准备好全链路多币种前,不贸然展示。这是金融场景该有的保守——&quot;看到的价必须等于扣的价&quot;是底线,任何展示层多币种都要在保证这条底线的前提下推进。</p><hr><h2 id="结语" tabindex="-1"><a class="header-anchor" href="#结语"><span>结语</span></a></h2><p>多语言商品内容不是 UI 翻译,是数据建模问题。这套架构的核心是三件事:</p><ol><li><strong>base/translation 分裂 + 复合唯一索引</strong>,让多语言内容成为一等数据公民。对比 JSONB,它在索引可用性、字段约束、事务粒度上都更优。</li><li><strong>可复用的 TranslationTabs 组件 + 语言字典驱动</strong>,让&quot;新增语种/新增可翻译字段&quot;的成本接近配置变更。字典驱动让语言清单受控,声明式字段配置让 UI 随 schema 演进。</li><li><strong>URL locale 作为路由一等公民</strong>,前台展示与 SEO 都建立在显式 locale 上。prefix 策略在 SEO、缓存、合规三者间最优。</li></ol><p>币种侧,它选择了&quot;展示层为多币种预留、结算层收敛单一币种&quot;的保守路线——schema 留了口子,运行守了底线。这是金融场景该有的工程保守:&quot;看到的价必须等于扣的价&quot;是底线,任何展示层多币种都要在保证这条底线的前提下推进。</p><p>这套方案不是万能的——JSONB 在&quot;语言数极少且查询模式简单&quot;时也够用,全币种结算在&quot;有完善汇率对冲和合规团队&quot;时也可行。但对一个面向出海、语言数会增长、需要受控币种的电商脚手架,这套取舍是结构上合理的。</p><p>仓库地址: GitHub <a href="https://github.com/tx7do/go-wind-shop" target="_blank" rel="noopener noreferrer">https://github.com/tx7do/go-wind-shop</a>, Gitee <a href="https://gitee.com/tx7do/go-wind-shop" target="_blank" rel="noopener noreferrer">https://gitee.com/tx7do/go-wind-shop</a>。 所有文中配置和代码均可逐行核对。</p>`,158)])])}const i=s(o,[["render",p]]),r=JSON.parse(`{"path":"/posts/go-wind-shop-internationalization-and-going-global.html","title":"GoWind Shop 出海实战:多语言商品内容怎么存、怎么录、怎么按 locale 取","lang":"zh-CN","frontmatter":{"date":"2026-08-11T00:00:00.000Z","category":["GoWind风行"],"tag":["Golang","GoWind","Vue","Shop"],"sticky":10},"headers":[{"level":2,"title":"一个常见误解","slug":"一个常见误解","link":"#一个常见误解","children":[]},{"level":2,"title":"一、数据层:base 表 + translation 表的分裂模式","slug":"一、数据层-base-表-translation-表的分裂模式","link":"#一、数据层-base-表-translation-表的分裂模式","children":[{"level":3,"title":"1.1 ProductTranslation 的字段结构","slug":"_1-1-producttranslation-的字段结构","link":"#_1-1-producttranslation-的字段结构","children":[]}]},{"level":2,"title":"二、proto 层:把\\"多语言\\"写进契约","slug":"二、proto-层-把-多语言-写进契约","link":"#二、proto-层-把-多语言-写进契约","children":[{"level":3,"title":"2.1 店铺前台 proto 的复用","slug":"_2-1-店铺前台-proto-的复用","link":"#_2-1-店铺前台-proto-的复用","children":[]}]},{"level":2,"title":"三、语言字典:哪些语言\\"存在\\",是受控的","slug":"三、语言字典-哪些语言-存在-是受控的","link":"#三、语言字典-哪些语言-存在-是受控的","children":[]},{"level":2,"title":"四、后台录入:TranslationTabs 组件,一处编辑所有语言","slug":"四、后台录入-translationtabs-组件-一处编辑所有语言","link":"#四、后台录入-translationtabs-组件-一处编辑所有语言","children":[{"level":3,"title":"4.1 组件契约:声明式字段配置","slug":"_4-1-组件契约-声明式字段配置","link":"#_4-1-组件契约-声明式字段配置","children":[]},{"level":3,"title":"4.2 组件行为:字典驱动 + 每语言一条保证","slug":"_4-2-组件行为-字典驱动-每语言一条保证","link":"#_4-2-组件行为-字典驱动-每语言一条保证","children":[]},{"level":3,"title":"4.3 各实体怎么用","slug":"_4-3-各实体怎么用","link":"#_4-3-各实体怎么用","children":[]},{"level":3,"title":"4.4 列表页怎么展示","slug":"_4-4-列表页怎么展示","link":"#_4-4-列表页怎么展示","children":[]}]},{"level":2,"title":"五、店铺前台:URL locale 作为路由一等公民","slug":"五、店铺前台-url-locale-作为路由一等公民","link":"#五、店铺前台-url-locale-作为路由一等公民","children":[{"level":3,"title":"5.1 翻译文案文件结构","slug":"_5-1-翻译文案文件结构","link":"#_5-1-翻译文案文件结构","children":[]},{"level":3,"title":"5.2 前台取商品时的 locale 传递","slug":"_5-2-前台取商品时的-locale-传递","link":"#_5-2-前台取商品时的-locale-传递","children":[]},{"level":3,"title":"5.3 一个已知边界","slug":"_5-3-一个已知边界","link":"#_5-3-一个已知边界","children":[]}]},{"level":2,"title":"六、横向对比:四种多语言内容存储方案","slug":"六、横向对比-四种多语言内容存储方案","link":"#六、横向对比-四种多语言内容存储方案","children":[{"level":3,"title":"方案 A:JSONB 列存多语言(主流方案之一)","slug":"方案-a-jsonb-列存多语言-主流方案之一","link":"#方案-a-jsonb-列存多语言-主流方案之一","children":[]},{"level":3,"title":"方案 B:每语言一张表","slug":"方案-b-每语言一张表","link":"#方案-b-每语言一张表","children":[]},{"level":3,"title":"方案 C(本方案):base + translation 分裂 + 复合唯一索引","slug":"方案-c-本方案-base-translation-分裂-复合唯一索引","link":"#方案-c-本方案-base-translation-分裂-复合唯一索引","children":[]},{"level":3,"title":"方案 D:URL locale 的三种策略对比","slug":"方案-d-url-locale-的三种策略对比","link":"#方案-d-url-locale-的三种策略对比","children":[]}]},{"level":2,"title":"七、多币种:展示层支持多币种,结算层收敛单一币种","slug":"七、多币种-展示层支持多币种-结算层收敛单一币种","link":"#七、多币种-展示层支持多币种-结算层收敛单一币种","children":[{"level":3,"title":"7.1 展示层:SKU 多币种价格表的 schema","slug":"_7-1-展示层-sku-多币种价格表的-schema","link":"#_7-1-展示层-sku-多币种价格表的-schema","children":[]},{"level":3,"title":"7.2 结算层:Currency mixin 默认且当前仅 CNY","slug":"_7-2-结算层-currency-mixin-默认且当前仅-cny","link":"#_7-2-结算层-currency-mixin-默认且当前仅-cny","children":[]},{"level":3,"title":"7.3 前台消费:目前实际只取 CNY 那一行","slug":"_7-3-前台消费-目前实际只取-cny-那一行","link":"#_7-3-前台消费-目前实际只取-cny-那一行","children":[]},{"level":3,"title":"7.4 诚实交代当前边界","slug":"_7-4-诚实交代当前边界","link":"#_7-4-诚实交代当前边界","children":[]},{"level":3,"title":"7.5 对比:三种币种策略","slug":"_7-5-对比-三种币种策略","link":"#_7-5-对比-三种币种策略","children":[]}]},{"level":2,"title":"结语","slug":"结语","link":"#结语","children":[]}],"git":{"updatedTime":1786420471000,"contributors":[{"name":"Bobo","username":"Bobo","email":"yanglinbo@gmail.com","commits":1,"url":"https://github.com/Bobo"}],"changelog":[{"hash":"e2ce92e3de85c275b0b5b0183aebe03348e2dd79","time":1786420471000,"email":"yanglinbo@gmail.com","author":"Bobo","message":"feat: add posts."}]},"filePathRelative":"posts/go-wind-shop-internationalization-and-going-global.md","excerpt":"\\n<h2>一个常见误解</h2>\\n<p>很多团队对\\"国际化\\"的理解停留在前端字符串翻译——<code>zh.json</code>/<code>en.json</code> 切换一下 <code>t('hello')</code> 就完事。但对电商而言,真正的难点不在 UI 文案,而在<strong>商品内容的多语言化</strong>。</p>\\n<p>一件商品的中文名、英文名、商品描述、类目路径——这些是入库的业务数据,不是 UI 文案。你不能把它们塞进 <code>zh.json</code>,因为:</p>\\n<ul>\\n<li>不同语言的商品描述要分别审核、分别上下架。</li>\\n<li>同一件商品的\\"主数据\\"(SKU、价格、库存、类目归属)是语言无关的,只有\\"展示文案\\"按语言分叉。</li>\\n<li>后台编辑时,运营要在同一界面同时维护所有语言版本,而不是切来切去。</li>\\n<li>店铺前台要能按 URL 里的 locale 一次性取到对应语言版本,而不是取全量再前端过滤。</li>\\n</ul>"}`);export{i as comp,r as data};
